// Building behaviour hard-coded in the server (game/server/tf/tf_obj*.cpp, plus the
// SENTRYGUN_* / DISPENSER_* defines in game/shared/tf/tf_shareddefs.h).

/** ObjectType_t (tf_shareddefs.h). */
export const OBJECT_TYPE = {
  OBJ_DISPENSER: 0,
  OBJ_TELEPORTER: 1,
  OBJ_SENTRYGUN: 2,
  OBJ_ATTACHMENT_SAPPER: 3,
} as const;

/** Shared object rules (tf_obj.cpp / tf_obj.h). */
export const BUILDING = {
  /** UPGRADE_LEVEL_HEALTH_MULTIPLIER: max health × 1.2 per level above 1 (150 → 180 → 216). */
  levelHealthMult: 1.2,
  maxLevel: 3,
  /** OBJECT_CONSTRUCTION_STARTINGHEALTH: health at placement; it grows with build progress. */
  constructionStartHealth: 0.1,
  /** OBJECT_CONSTRUCTION_INTERVAL: construction think. */
  constructionInterval: 0.1,
  /**
   * Build speed multiplier = 1 + 1.5 for each wrench hit in the last second
   * (tf_construction_build_rate_multiplier; see weapons.ts WRENCH).
   */
  wrenchBuildBonus: 1.5,
  /** tf_obj_upgrade_per_hit. */
  upgradeMetalPerHit: 25,
  /** Wrench repair: 100 HP per hit at 3 HP per metal. */
  repairPerHit: 100,
  repairHealthPerMetal: 3,
  /** OBJECT_REPAIR_RATE (health/s, other repair sources). */
  repairRate: 10,
  /** Carrying a building slows the Engineer to 90%. */
  carrySpeedMult: 0.9,
  /** tf_obj_ground_clearance: footprint corners may be this far above the ground. */
  groundClearance: 32,
  /** Gibs (tf_obj_gib_*). */
  gibVelocityMin: 100,
  gibVelocityMax: 450,
  gibMaxSpeed: 800,
  /** tf_obj_build_rotation_speed (baseobject_shared.cpp): blueprint rotation, degrees/s. */
  blueprintRotationSpeed: 250,
} as const;

/** Health of a building at a level (CBaseObject::GetMaxHealthForCurrentLevel). */
export function buildingMaxHealth(baseHealth: number, level: number): number {
  return level > 1 ? Math.trunc(baseHealth * BUILDING.levelHealthMult ** (level - 1)) : baseHealth;
}

